Create two components: one for the text editor and another for the multi-select list.

#### Text Editor Component (`textEditor.component.ts`)

```typescript
import { Component } from '@angular/core';
import { TextEditorModule } from 'ngx-text-editor';

@Component({
  selector: 'app-text-editor',
  templateUrl: './text-editor.component.html',
  styleUrls: ['./text-editor.component.css']
})
export class TextEditorComponent {
  content = '';

  onChange(content: string) {
    this.content = content;
  }
}
```

#### Multi-Select List Component (`multiSelectList.component.ts`)

```typescript
import { Component } from '@angular/core';
import { MatMultiselectListModule } from '@angular/material/multiselect-list';

@Component({
  selector: 'app-multi-select-list',
  templateUrl: './multi-select-list.component.html',
  styleUrls: ['./multi-select-list.component.css']
})
export class MultiSelectListComponent {
  items = [
    { value: 'Item 1', label: 'Item 1' },
    { value: 'Item 2', label: 'Item 2' },
    { value: 'Item 3', label: 'Item 3' },
    // Add more items as needed
  ];

  selectedItems = [];

  onSelectionChange(items: any[]) {
    this.selectedItems = items;
  }
}
```

### Step 3: Set Up Routing

If you want to use routing, create a route configuration file (`routes.module.ts`) or import it into your main app module.

```typescript
import { NgModule } from '@angular/core';
import { RouterModule, Routes } from '@angular/router';
import { TextEditorComponent } from './components/text-editor/text-editor.component';
import { MultiSelectListComponent } from './components/multi-select-list/multi-select-list.component';

const routes: Routes = [
  { path: '', component: TextEditorComponent },
  { path: 'multi-select-list', component: MultiSelectListComponent }
];

@NgModule({
  imports: [RouterModule.forRoot(routes)],
  exports: [RouterModule]
})
export class AppRoutingModule {}
```

