	sourceFilePath := os.Args[1]
	structName := os.Args[2]

	// Parse the source file
	file, err := parser.ParseFile(token.NewFileSet(), sourceFilePath, nil, parser.ParseComments)
	if err != nil {
		fmt.Printf("Error parsing file %s: %v\n", sourceFilePath, err)
		return
	}

	// Extract fields from the struct definition
	var structInfo StructInfo
	ast.Walk(func(node ast.Node) error {
		switch n := node.(type) {
		case *ast.Field:
			field := &StructInfo{
